def describe(exc):
    if exc is None:
        return "ok"
    if isinstance(exc, Exit):
        return f"Exit({exc.exit_code})"
    return type(exc).__name__


def track_parse(ctx, param, value):
    name = ctx.info_name
    click.echo(f"parse {name}")
    ctx.call_on_close(lambda: click.echo(f"close {name}"))
    return value


def test_non_chain_full_event_sequence(runner):
