def build_chain(fail_on=None):
    @click.group(chain=True)
    def cli():
        click.echo("group")

    @cli.before_subcommand
    def before(ctx):
        click.echo(f"before {ctx.info_name}")

    @cli.after_subcommand
    def after(ctx, result):
        click.echo(f"after {ctx.info_name} {result!r}")

    @cli.teardown_subcommand
    def teardown(ctx, exc):
        click.echo(f"teardown {ctx.info_name} {describe(exc)}")

    @cli.result_callback()
    def done(results):
        click.echo(f"results {results!r}")

    def make(name, value):
        @cli.command(name)
        @click.option("--x", callback=track_parse)
        def cmd(x):
            click.echo(name)
            if name == fail_on:
                raise click.ClickException(f"{name} failed")
            return value

    for name, value in (("a", 1), ("b", 2), ("c", 3)):
        make(name, value)

    return cli


