def build_nested(leaf_raises):
    @click.group()
    def outer():
        click.echo("outer")

    @outer.before_subcommand
    def ob(ctx):
        click.echo(f"outer-before {ctx.info_name}")

    @outer.after_subcommand
    def oa(ctx, result):
        click.echo(f"outer-after {ctx.info_name} {result!r}")

    @outer.teardown_subcommand
    def ot(ctx, exc):
        click.echo(f"outer-teardown {ctx.info_name} {describe(exc)}")

    @outer.result_callback()
    def outer_done(result):
        click.echo(f"outer-result {result!r}")

    @outer.group()
    @click.pass_context
    def inner(ctx):
        ctx.call_on_close(lambda: click.echo("close inner"))
        click.echo("inner")

    @inner.before_subcommand
    def ib(ctx):
        click.echo(f"inner-before {ctx.info_name}")

    @inner.after_subcommand
    def ia(ctx, result):
        click.echo(f"inner-after {ctx.info_name} {result!r}")

    @inner.teardown_subcommand
    def it(ctx, exc):
        click.echo(f"inner-teardown {ctx.info_name} {describe(exc)}")

    @inner.result_callback()
    def inner_done(result):
        click.echo(f"inner-result {result!r}")
        return "inner-rv"

    @inner.command()
    @click.pass_context
    def leaf(ctx):
        ctx.call_on_close(lambda: click.echo("close leaf"))
        click.echo("leaf")
        if leaf_raises:
            raise click.SkipSubcommand()
        return "leaf-rv"

    return outer


